using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using NetworkHub.App;
using NetworkHub.Dns;

namespace NetworkHub.Desktop;

internal static class TestsDns
{
    internal sealed class FakeSettings : IDnsSettingsReader,IDnsSettingsWriter
    {
        internal DnsSnapshot State=Initial();internal int Writes;internal Action<DnsFamily>? BeforeWrite {get;set;}internal Action? AfterWrite {get;set;}internal Func<DnsSnapshot,DnsSnapshot>? ReadOverride {get;set;}internal string? PersistPath;
        public IReadOnlyList<DnsAdapter> Adapters()=>new[]{new DnsAdapter(State.AdapterId,"Fixture Ethernet","Ethernet",true,false)};
        public DnsSnapshot Read(Guid id)=>id==State.AdapterId?ReadOverride?.Invoke(State)??State:throw new DnsException("The selected adapter is no longer available.");
        public void Write(Guid id,DnsFamily family,DnsFamilySettings value){if(id!=State.AdapterId)throw new InvalidOperationException();BeforeWrite?.Invoke(family);State=State.With(family,value);Writes++;if(PersistPath!=null){Directory.CreateDirectory(Path.GetDirectoryName(PersistPath)!);File.WriteAllText(PersistPath,System.Text.Json.JsonSerializer.Serialize(State));}AfterWrite?.Invoke();}
    }
    internal sealed class FakeStore : IDnsJournalStore
    {
        internal DnsJournal? Journal;internal int Saves;internal int FailOn;internal Func<DnsJournal,DnsJournal>? ReadOverride;
        public DnsJournal? Load(Guid id)=>Journal==null?null:ReadOverride?.Invoke(Journal)??Journal;
        public void Save(DnsJournal journal){Saves++;if(Saves==FailOn)throw new IOException("Injected persistence failure");Journal=journal;}
    }
    sealed class FailedInspection : IDnsSettingsReader
    {
        public IReadOnlyList<DnsAdapter> Adapters()=>throw new IOException("Injected read failure");
        public DnsSnapshot Read(Guid adapter)=>throw new IOException("Injected read failure");
    }
    internal sealed class FakeProbes : IDnsProbeRunner
    {
        public Task<DnsProbeResult> Run(Uri endpoint,CancellationToken token,DnsProbeKind kind=DnsProbeKind.Both)=>Task.FromResult(new DnsProbeResult(endpoint.Host,kind!=DnsProbeKind.Https,kind==DnsProbeKind.Names?null:403,"192.0.2.10","HTTPS endpoint responded. This does not prove that the service or account works."){NamesRequested=kind!=DnsProbeKind.Https,HttpsRequested=kind!=DnsProbeKind.Names,FinishedUtc=DateTime.UtcNow.ToString("O")});
    }
    internal static FakeSettings Fixture(string? root=null){var fixture=new FakeSettings();if(root!=null){fixture.PersistPath=Path.Combine(root,"Dns","SimulatedState.json");if(File.Exists(fixture.PersistPath))fixture.State=System.Text.Json.JsonSerializer.Deserialize<DnsSnapshot>(File.ReadAllText(fixture.PersistPath))??throw new InvalidDataException("Invalid simulated DNS state");}return fixture;}
    static DnsSnapshot Initial()=>new(Guid.Parse("39d9b083-f28a-4e98-85ef-15ea30d945b2"),"Fixture Ethernet","fixture-machine",new(DnsMode.Manual,new[]{"192.0.2.53","192.0.2.54"},new[]{"192.0.2.53","192.0.2.54"}),new(DnsMode.Automatic,Array.Empty<string>(),new[]{"2001:db8::53"}),"fixture-dependencies",true,"");
    static DnsSnapshot Target(DnsSnapshot before,bool both=false)=>before.With(DnsFamily.IPv4,new(DnsMode.Manual,new[]{"83.220.169.155","212.109.195.93"},Array.Empty<string>())).With(DnsFamily.IPv6,both?new(DnsMode.Manual,new[]{"2001:db8::1"},Array.Empty<string>()):before.IPv6);
    static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    static void Reject(Action action){try{action();}catch(Exception ex)when(ex is DnsException or IOException or System.Text.Json.JsonException or InvalidDataException){return;}throw new Exception("Unsafe operation was accepted");}
    internal static void Run(Action<string,Action> test,Shell shell,AppFiles files)
    {
        TestsDnsSessions.Run(test,shell,files);
        TestsDnsReapply.Run(test,files);
        test("DNS: saved backup must read back exactly before any write",()=>{var backend=Fixture();var before=backend.State;var store=new FakeStore{ReadOverride=j=>j with{Before=j.Before with{DependencyFingerprint="corrupt-readback"}}};Reject(()=>new DnsTransaction(backend,backend,store,"test").Apply(before,Target(before),new[]{DnsFamily.IPv4}));Assert(backend.Writes==0&&store.Journal!=null,"Write occurred without verified baseline");});
        test("DNS: catalog template alone does not activate adapter encryption",()=>{var before=Initial();var profile=DnsProfiles.All[0];var target=DnsProfiles.ManualPlan(before.IPv4,profile.IPv4,profile);Assert(target.Encryption.Length==0,"Catalog information treated as active DoH");var disabled=before.IPv4 with{Encryption=new[]{new DnsDohSettings(before.IPv4.Servers[0],null,0)}};Assert(DnsProfiles.ManualPlan(disabled,profile.IPv4,profile).Encryption.Length==0,"Disabled rule treated as active DoH");});
        test("DNS: encrypted Xbox to Comss and exact encrypted restoration across restart",()=>{string path=Path.Combine(files.Data,"Dns-doh-restart",Guid.NewGuid().ToString("N"));var backend=Fixture(path);var xbox=DnsProfiles.All.First(p=>p.Id=="xbox");backend.State=backend.State.With(DnsFamily.IPv4,new(DnsMode.Manual,xbox.IPv4,xbox.IPv4){Encryption=xbox.IPv4.Select(s=>new DnsDohSettings(s,xbox.Doh,2)).ToArray()});var before=backend.State;var comss=DnsProfiles.All.First(p=>p.Id=="comss");var target=before.With(DnsFamily.IPv4,DnsProfiles.ManualPlan(before.IPv4,comss.IPv4,comss));var store=new DnsFileJournalStore(path,"test");new DnsTransaction(backend,backend,store,"test").Apply(before,target,new[]{DnsFamily.IPv4},"comss");Assert(backend.State.IPv4.Encryption.All(p=>p.Flags==2&&p.Template==comss.Doh)&&backend.State.IPv6.SameConfiguration(before.IPv6),"Encryption downgraded or IPv6 changed");var restarted=Fixture(path);new DnsTransaction(restarted,restarted,new DnsFileJournalStore(path,"test"),"test").Restore(before.AdapterId,restarted.State.Fingerprint());Assert(restarted.State.SameConfiguration(before)&&restarted.State.IPv4.Encryption.SequenceEqual(before.IPv4.Encryption),"Original encrypted DNS not restored");});
        test("DNS: encryption downgrade and template substitution rejected",()=>{var backend=Fixture();var profile=DnsProfiles.All[0];var before=backend.State with{IPv4=backend.State.IPv4 with{Encryption=backend.State.IPv4.Servers.Select(s=>new DnsDohSettings(s,"https://dns.example/dns-query",2)).ToArray()}};backend.State=before;var store=new FakeStore();Reject(()=>new DnsTransaction(backend,backend,store,"test").Apply(before,Target(before),new[]{DnsFamily.IPv4}));var target=before.With(DnsFamily.IPv4,DnsProfiles.ManualPlan(before.IPv4,profile.IPv4,profile));Reject(()=>DnsProfiles.ValidateSelection("comss",target with{IPv4=target.IPv4 with{Encryption=target.IPv4.Encryption.Select(p=>p with{Template="https://other.example/dns-query"}).ToArray()}},new[]{DnsFamily.IPv4}));Reject(()=>DnsProfiles.ManualPlan(before.IPv4,new[]{"192.0.2.1"},DnsProfiles.All.First(p=>p.Id=="custom")));Assert(backend.Writes==0,"Rejected plan wrote settings");});
        test("DNS: per-adapter DoH native plan preserves indexes flags and templates",()=>{foreach(ulong flags in new[]{2UL,6UL,1UL,5UL,10UL}){var values=new DnsFamilySettings(DnsMode.Manual,new[]{"192.0.2.53","192.0.2.54"},Array.Empty<string>()){Encryption=new[]{new DnsDohSettings("192.0.2.54",(flags&1)!=0?null:"https://dns.example/dns-query",flags)}};using var plan=new WindowsDnsSettings.NativeWritePlan(DnsFamily.IPv4,values);Assert(plan.Value.Version==3&&plan.Value.Flags==0x1002&&plan.Value.ServerCount==1,"Wrong native scope/version");var copied=WindowsDnsSettings.CopyProperties(plan.Value.ServerCount,plan.Value.ServerProperties,values.Servers);Assert(copied.SequenceEqual(values.Encryption),"Native property round trip lost settings");}using var plain=new WindowsDnsSettings.NativeWritePlan(DnsFamily.IPv6,new(DnsMode.Manual,new[]{"2001:db8::53"},Array.Empty<string>()));Assert(plain.Value.Flags==3&&plain.Value.ServerCount==0,"IPv6 scope");});
        test("DNS: template-only external change blocks restore",()=>{var backend=Fixture();backend.State=backend.State with{IPv4=backend.State.IPv4 with{Encryption=backend.State.IPv4.Servers.Select(s=>new DnsDohSettings(s,"https://dns.example/dns-query",2)).ToArray()}};var before=backend.State;var profile=DnsProfiles.All[0];var target=before.With(DnsFamily.IPv4,DnsProfiles.ManualPlan(before.IPv4,profile.IPv4,profile));var tx=new DnsTransaction(backend,backend,new FakeStore(),"test");tx.Apply(before,target,new[]{DnsFamily.IPv4},"comss");backend.State=backend.State with{IPv4=backend.State.IPv4 with{Encryption=backend.State.IPv4.Encryption.Select(p=>p with{Template="https://foreign.example/dns-query"}).ToArray()}};Reject(()=>tx.Restore(before.AdapterId,backend.State.Fingerprint()));Assert(backend.Writes==1,"Foreign template overwritten");});
        test("DNS: owned profile identity survives restart without IP inference",()=>{string path=Path.Combine(files.Data,"Dns-profile-test",Guid.NewGuid().ToString("N"));var backend=Fixture(path);var before=backend.State;var store=new DnsFileJournalStore(path,"test");var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before),new[]{DnsFamily.IPv4},"comss");var reloaded=new DnsFileJournalStore(path,"test").Load(before.AdapterId)!;Assert(reloaded.ProfileId=="comss"&&DnsManagerView.ProfileStatus(reloaded)=="Profile ComssDNS","Owned profile lost");Assert(DnsManagerView.ProfileStatus(reloaded with{ProfileId=""})=="A DNS profile is applied by Open Net.","Guessed identity from DNS addresses");tx.Restore(before.AdapterId,backend.State.Fingerprint());Reject(()=>tx.Apply(backend.State,Target(before),new[]{DnsFamily.IPv4},"xbox"));Assert(backend.Writes==2,"Mismatched profile changed DNS");});
        test("DNS: inspection failure keeps settings window available and actions disabled",()=>{new System.Windows.Interop.WindowInteropHelper(shell.Window).EnsureHandle();DnsManagerView.ReaderForTests=new FailedInspection();try{var manager=new DnsManagerView(shell,files);try{Assert(!((Button)manager.Window.FindName("DnsApply")).IsEnabled&&!((Button)manager.Window.FindName("DnsRestore")).IsEnabled,"Failed inspection allowed writes");Assert(((TextBlock)manager.Window.FindName("DnsReason")).Text.Length>0,"No disabled reason");}finally{manager.Window.Close();}}finally{DnsManagerView.ReaderForTests=null;}});
        test("DNS: manual IPv4 order and independent IPv6 restore",()=>{var backend=Fixture();var before=backend.State;var store=new FakeStore();var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before),new[]{DnsFamily.IPv4});Assert(backend.State.IPv6.SameConfiguration(before.IPv6)&&backend.Writes==1,"Unselected IPv6 changed");Assert(store.Journal!.Before.IPv4.Servers.SequenceEqual(before.IPv4.Servers),"Order lost");tx.Restore(before.AdapterId,backend.State.Fingerprint());Assert(backend.State.SameConfiguration(before)&&store.Journal.Phase==DnsPhase.Restored,"Manual baseline not restored");});
        test("DNS: automatic mode survives changed DHCP lease",()=>{var backend=Fixture();backend.State=backend.State.With(DnsFamily.IPv4,new(DnsMode.Automatic,Array.Empty<string>(),new[]{"192.0.2.1"}));var before=backend.State;var store=new FakeStore();var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before),new[]{DnsFamily.IPv4});tx.Restore(before.AdapterId,backend.State.Fingerprint());backend.State=backend.State.With(DnsFamily.IPv4,backend.State.IPv4 with{EffectiveServers=new[]{"192.0.2.2"}});Assert(backend.State.SameConfiguration(before),"DHCP lease was treated as static");});
        test("DNS: invalid input and command injection rejected",()=>{foreach(string value in new[]{"","8.8.8.8; & calc","https://dns.example","127.0.0.1","0.0.0.0","224.0.0.1","8.8.8.8 8.8.8.8","1.1.1.1:53","8.8.8.8 1.1.1.1 9.9.9.9 4.4.4.4 2.2.2.2"})Reject(()=>DnsProfiles.Validate(value,DnsFamily.IPv4));foreach(string value in new[]{"::1","::","fe80::1%4","ff02::1","8.8.8.8"})Reject(()=>DnsProfiles.Validate(value,DnsFamily.IPv6));Assert(DnsProfiles.Validate("2001:0db8::1",DnsFamily.IPv6)[0]=="2001:db8::1","Normalization");});
        test("DNS: journal failure before write is fail-closed",()=>{var backend=Fixture();var store=new FakeStore{FailOn=1};Reject(()=>new DnsTransaction(backend,backend,store,"test").Apply(backend.State,Target(backend.State),new[]{DnsFamily.IPv4}));Assert(backend.Writes==0,"Write without backup");});
        test("DNS: baseline changes before application cancel write",()=>{var backend=Fixture();var before=backend.State;backend.State=Target(before);var store=new FakeStore();Reject(()=>new DnsTransaction(backend,backend,store,"test").Apply(before,Target(before),new[]{DnsFamily.IPv4}));Assert(backend.Writes==0&&store.Journal==null,"Baseline race");});
        test("DNS: partial write keeps durable recovery intent",()=>{var backend=Fixture();var before=backend.State;var store=new FakeStore{FailOn=3};var tx=new DnsTransaction(backend,backend,store,"test");Reject(()=>tx.Apply(before,Target(before,true),new[]{DnsFamily.IPv4,DnsFamily.IPv6}));Assert(backend.State.SameConfiguration(before)&&store.Journal!.Phase==DnsPhase.Restored,"Compensation lost original baseline");store.FailOn=0;tx.Restore(before.AdapterId,backend.State.Fingerprint());Assert(backend.State.SameConfiguration(before),"Pending write could not recover");});
        test("DNS: failures at every apply persistence boundary recover",()=>{for(int failure=2;failure<=6;failure++){var backend=Fixture();var before=backend.State;var store=new FakeStore{FailOn=failure};var tx=new DnsTransaction(backend,backend,store,"test");Reject(()=>tx.Apply(before,Target(before,true),new[]{DnsFamily.IPv4,DnsFamily.IPv6}));Assert(store.Journal!=null,"Baseline disappeared");store.FailOn=0;tx.Restore(before.AdapterId,backend.State.Fingerprint());Assert(backend.State.SameConfiguration(before),"Recovery boundary "+failure);}});
        test("DNS: foreign DNS or encryption changes block restore",()=>{foreach(bool encryption in new[]{false,true}){var backend=Fixture();var before=backend.State;var store=new FakeStore();var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before),new[]{DnsFamily.IPv4});backend.State=encryption?backend.State with{DependencyFingerprint="foreign-doh"}:backend.State.With(DnsFamily.IPv4,new(DnsMode.Manual,new[]{"192.0.2.99"},Array.Empty<string>()));Reject(()=>tx.Restore(before.AdapterId,backend.State.Fingerprint()));Assert(backend.Writes==1,"Foreign config overwritten");}});
        test("DNS: restoring resumes after every disk failure boundary",()=>{for(int offset=1;offset<=6;offset++){var backend=Fixture();var before=backend.State;var store=new FakeStore();var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before,true),new[]{DnsFamily.IPv4,DnsFamily.IPv6});store.FailOn=store.Saves+offset;Reject(()=>tx.Restore(before.AdapterId,backend.State.Fingerprint()));store.FailOn=0;tx.Restore(before.AdapterId,backend.State.Fingerprint());Assert(backend.State.SameConfiguration(before)&&store.Journal!.Phase==DnsPhase.Restored,"Restore boundary "+offset);}});
        test("DNS: verification failure and foreign change between families stop writes",()=>{var backend=Fixture();var before=backend.State;var store=new FakeStore();backend.BeforeWrite=f=>{if(f==DnsFamily.IPv4)backend.State=backend.State with{DependencyFingerprint="external-policy"};};var tx=new DnsTransaction(backend,backend,store,"test");Reject(()=>tx.Apply(before,Target(before,true),new[]{DnsFamily.IPv4,DnsFamily.IPv6}));Assert(backend.Writes==1&&store.Journal!.Pending==DnsFamily.IPv4,"Unsafe second-family write");Reject(()=>tx.Restore(before.AdapterId,backend.State.Fingerprint()));Assert(backend.Writes==1,"Foreign dependency overwritten");});
        test("DNS: missing adapter and wrong machine are blocked",()=>{var backend=Fixture();var before=backend.State;var store=new FakeStore();var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before),new[]{DnsFamily.IPv4});Reject(()=>tx.Restore(Guid.NewGuid(),backend.State.Fingerprint()));backend.State=backend.State with{MachineId="other-machine"};Reject(()=>tx.Restore(before.AdapterId,backend.State.Fingerprint()));Assert(backend.Writes==1,"Wrong identity write");});
        test("DNS: repeated apply preserves first baseline",()=>{var backend=Fixture();var before=backend.State;var store=new FakeStore();var tx=new DnsTransaction(backend,backend,store,"test");tx.Apply(before,Target(before),new[]{DnsFamily.IPv4});tx.Apply(backend.State,Target(backend.State),new[]{DnsFamily.IPv4});Assert(store.Journal!.Before.SameConfiguration(before)&&backend.Writes==1,"Original backup overwritten");});
        test("DNS: disk journal reload and corruption protection",()=>{string path=Path.Combine(files.Data,"Dns-tests",Guid.NewGuid().ToString("N"));var backend=Fixture(path);var before=backend.State;var store=new DnsFileJournalStore(path,"test");new DnsTransaction(backend,backend,store,"test").Apply(before,Target(before),new[]{DnsFamily.IPv4});var restarted=Fixture(path);var reloaded=new DnsFileJournalStore(path,"test");new DnsTransaction(restarted,restarted,reloaded,"test").Restore(before.AdapterId,restarted.State.Fingerprint());Assert(restarted.State.SameConfiguration(before),"Restart failed");Reject(()=>new DnsFileJournalStore(path,"foreign").Load(before.AdapterId));File.WriteAllText(Path.Combine(path,before.AdapterId.ToString("D")+".json"),"corrupt");Reject(()=>reloaded.Load(before.AdapterId));});
        test("DNS: unsupported policy and unknown source forbid apply",()=>{foreach(var before in new[]{Initial() with{CanChange=false},Initial() with{IPv6=new(DnsMode.Unknown,Array.Empty<string>(),Array.Empty<string>())}}){var backend=Fixture();backend.State=before;Reject(()=>new DnsTransaction(backend,backend,new FakeStore(),"test").Apply(before,Target(before),new[]{DnsFamily.IPv4}));Assert(backend.Writes==0,"Unsupported write");}});
        test("DNS: helper replay and fixed reset command guards",()=>{var before=Initial();var r=new DnsRequest(Guid.NewGuid().ToString("N"),123,456,"S-1-5-21-1","en","apply",before,Target(before),new[]{DnsFamily.IPv4},before.Fingerprint());Assert(DnsElevated.ValidRequest(r,r.Token),"Valid shape");Assert(!DnsElevated.ValidRequest(r with{Action="shell"},r.Token)&&!DnsElevated.ValidRequest(r,Guid.NewGuid().ToString("N")),"Unknown operation/replay");Assert(DnsElevated.Run(new[]{"--dns-elevated",r.Token,"--data-root",files.Data})==2,"Safe helper ran");var plan=WindowsDnsSettings.AutomaticResetPlan(12,DnsFamily.IPv6);Assert(!plan.UseShellExecute&&plan.ArgumentList.SequenceEqual(new[]{"interface","ipv6","set","dnsservers","name=12","source=dhcp"}),"Reset scope");});
        test("DNS: public service checks distinguish HTTP refusal",()=>{var probe=new FakeProbes().Run(new Uri("https://chatgpt.com/"),CancellationToken.None).GetAwaiter().GetResult();Assert(probe.DnsResolved&&probe.HttpStatus==403&&probe.HttpsDetail.Contains("does not prove"),"False service success");Assert(!DnsProfiles.All.First(x=>x.Id=="xbox").Available,"Outage profile selectable");});
        test("DNS: approved request hash prevents file substitution",()=>{string json="{\"Action\":\"apply\",\"Target\":\"83.220.169.155\"}";string hash=DnsElevated.RequestHash(json);Assert(DnsElevated.MatchesHash(System.Text.Encoding.UTF8.GetBytes(json),hash),"Hash mismatch");Assert(!DnsElevated.MatchesHash(System.Text.Encoding.UTF8.GetBytes(json.Replace("83.220.169.155","192.0.2.99")),hash)&&!DnsElevated.MatchesHash(System.Text.Encoding.UTF8.GetBytes(json),"bad"),"Mutable request accepted");});
        if(new System.Security.Principal.WindowsPrincipal(System.Security.Principal.WindowsIdentity.GetCurrent()).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator))test("DNS: protected journal ACL persists on owned temporary files",()=>{string directory=Path.Combine(files.Data,"Dns-acl-fixture",Guid.NewGuid().ToString("N"));string owner=DnsRecoveryStore.Owner();var store=new DnsFileJournalStore(directory,owner,path=>DnsRecoveryStore.ProtectFile(path,new System.Security.Principal.SecurityIdentifier(owner)));var backend=Fixture();var before=backend.State;new DnsTransaction(backend,backend,store,owner).Apply(before,Target(before),new[]{DnsFamily.IPv4});var info=new FileInfo(Path.Combine(directory,before.AdapterId.ToString("D")+".json"));var acl=System.IO.FileSystemAclExtensions.GetAccessControl(info);Assert(acl.GetOwner(typeof(System.Security.Principal.SecurityIdentifier))!.Value=="S-1-5-32-544","Trusted journal owner");foreach(System.Security.AccessControl.FileSystemAccessRule rule in acl.GetAccessRules(true,true,typeof(System.Security.Principal.SecurityIdentifier))){if(rule.IdentityReference.Value==owner)Assert((rule.FileSystemRights&(System.Security.AccessControl.FileSystemRights.Write|System.Security.AccessControl.FileSystemRights.ChangePermissions))==0,"User writable record");}Assert(store.Load(before.AdapterId)!.Phase==DnsPhase.Applied,"Protected reload");});
        test("DNS: UI is separate from process selection and startup",()=>{var saved=shell.Settings.Copy();new System.Windows.Interop.WindowInteropHelper(shell.Window).EnsureHandle();var view=new DnsManagerView(shell,files).Window;try{var apply=(Button)view.FindName("DnsApply");var restore=(Button)view.FindName("DnsRestore");Assert(apply.IsEnabled&&!restore.IsEnabled,"Remembered valid profile must be ready, never applied on open");var profiles=(ComboBox)view.FindName("DnsProfile");profiles.SelectedIndex=1;Assert(apply.IsEnabled,"Valid profile disabled");profiles.SelectedIndex=2;Assert(apply.IsEnabled,"Outage must not block simulation");profiles.SelectedIndex=3;((TextBox)view.FindName("DnsAddresses4")).Text="83.220.169.155";Assert(apply.IsEnabled,"Custom validation");Assert(shell.Settings.ZapretSelected==saved.ZapretSelected&&shell.Settings.TgSelected==saved.TgSelected&&shell.Runtime.LaunchCount==0,"DNS entered process lifecycle");foreach(string mode in new[]{"dark","light"}){ThemeManager.SetMode(mode);var content=(FrameworkElement)view.Content;content.Measure(new Size(560,760));content.Arrange(new Rect(0,0,560,760));content.UpdateLayout();Assert(((ScrollViewer)view.FindName("DnsScroll")).HorizontalScrollBarVisibility==ScrollBarVisibility.Disabled,"Layout");}}finally{view.Close();}});
    }
    internal static async Task Interactive(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
    {
        await TestsDnsReapplyUi.Run(shell,files,test);
        await TestsDnsSessionUi.Run(shell,files,test);
        await test("DNS encrypted simulation confirms template and restores exact DoH",async()=>{
            var fixture=Fixture(files.Data);var initial=fixture.State;var xbox=DnsProfiles.All.First(p=>p.Id=="xbox");var encrypted=initial with{IPv4=new(DnsMode.Manual,xbox.IPv4,xbox.IPv4){Encryption=xbox.IPv4.Select(s=>new DnsDohSettings(s,xbox.Doh,2)).ToArray()}};
            Directory.CreateDirectory(Path.GetDirectoryName(fixture.PersistPath!)!);File.WriteAllText(fixture.PersistPath!,System.Text.Json.JsonSerializer.Serialize(encrypted));
            var manager=new DnsManagerView(shell,files);try{manager.Window.Show();((ComboBox)manager.Window.FindName("DnsProfile")).SelectedIndex=1;manager.ConfirmationForTests=message=>{Assert(message.Contains(xbox.Doh!)&&message.Contains(DnsProfiles.All[0].Doh!),"DoH diff missing from confirmation");return true;};((Button)manager.Window.FindName("DnsApply")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);Assert(Fixture(files.Data).State.IPv4.Encryption.All(p=>p.Flags==2&&p.Template==DnsProfiles.All[0].Doh),"UI downgraded DoH");manager.ConfirmationForTests=_=>true;((Button)manager.Window.FindName("DnsRestore")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);Assert(Fixture(files.Data).State.SameConfiguration(encrypted),"UI did not restore encrypted baseline");}finally{manager.Window.Close();File.WriteAllText(fixture.PersistPath!,System.Text.Json.JsonSerializer.Serialize(initial));}
        });
        await test("DNS Configure click restores minimized and hidden settings window",async()=>{
            shell.Find<Button>("DnsSettings").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var window=shell.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("DnsProfile")!=null);
            try{Assert(window.IsVisible,"Configure failed");window.WindowState=WindowState.Minimized;shell.Find<Button>("DnsSettings").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Assert(window.WindowState==WindowState.Normal,"Still minimized");window.Hide();shell.Find<Button>("DnsSettings").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Assert(window.IsVisible,"Still hidden");Assert(!((Button)window.FindName("DnsRestore")).IsEnabled&&((TextBlock)window.FindName("DnsReason")).Text.Length>0,"Missing restore explanation");await Task.Delay(30);}finally{window.Close();}
        });
        await test("DNS window confirmation, simulated apply/restore and native themed preview",async()=>{
            string language=L.Language,theme=ThemeManager.Mode;var saved=shell.Settings.Copy();
            try{
                L.Set("ru");ThemeManager.SetMode("dark");var manager=new DnsManagerView(shell,files);var window=manager.Window;window.Show();
                try{
                    var profiles=(ComboBox)window.FindName("DnsProfile");profiles.SelectedIndex=1;
                    manager.ConfirmationForTests=_=>false;await manager.OperationForTests(false);
                    Assert(((Button)window.FindName("DnsApply")).IsEnabled&&!((Button)window.FindName("DnsRestore")).IsEnabled,"Cancelled operation changed state");
                    manager.ConfirmationForTests=text=>{Assert(text.Contains("192.0.2.53")&&text.Contains("83.220.169.155"),"Missing confirmation diff");return true;};
                    foreach(string mode in new[]{"dark","light"}){ThemeManager.SetMode(mode);window.UpdateLayout();SelfTests.Capture(window,Path.Combine(files.Data,"dns-"+mode+"-before.png"));SelfTests.Capture(shell.Window,Path.Combine(files.Data,"dns-main-"+mode+".png"));}
                    ((Button)window.FindName("DnsApply")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);Assert(((Button)window.FindName("DnsRestore")).IsEnabled&&!((Button)window.FindName("DnsApply")).IsEnabled,"Apply state");SelfTests.Capture(window,Path.Combine(files.Data,"dns-applied.png"));
                    var restarted=new DnsManagerView(shell,files);try{Assert(((Button)restarted.Window.FindName("DnsRestore")).IsEnabled,"Restart lost simulated restoration");}finally{restarted.Window.Close();}
                    manager.ConfirmationForTests=_=>true;((Button)window.FindName("DnsRestore")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);Assert(!((Button)window.FindName("DnsRestore")).IsEnabled&&((Button)window.FindName("DnsApply")).IsEnabled,"Restoration state");
                    profiles.SelectedIndex=2;Assert(((Button)window.FindName("DnsApply")).IsEnabled,"Xbox simulation disabled");((Button)window.FindName("DnsApply")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);Assert(Fixture(files.Data).State.IPv4.Servers.SequenceEqual(DnsProfiles.All.First(p=>p.Id=="xbox").IPv4),"Xbox simulation did not apply");((Button)window.FindName("DnsRestore")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(30);Assert(Fixture(files.Data).State.SameConfiguration(Initial()),"Simulation did not restore baseline");SelfTests.Capture(window,Path.Combine(files.Data,"dns-xbox-warning.png"));
                    foreach(double scale in new[]{1.0,1.25,1.5,2.0}){var content=(FrameworkElement)window.Content;content.LayoutTransform=new System.Windows.Media.ScaleTransform(scale,scale);window.UpdateLayout();Assert(((ScrollViewer)window.FindName("DnsScroll")).HorizontalScrollBarVisibility==ScrollBarVisibility.Disabled,"Horizontal overflow policy");content.LayoutTransform=System.Windows.Media.Transform.Identity;}
                    Assert(shell.Settings.ZapretSelected==saved.ZapretSelected&&shell.Settings.TgSelected==saved.TgSelected,"Process selection changed");
                }finally{window.Close();}
            }finally{L.Set(language);ThemeManager.SetMode(theme);}
        });
    }
}
